def check_if_prerequisite(n, prerequisites, queries):
    adj = defaultdict(list)
    for a, b in prerequisites:
        adj[a].append(b)

    def reaches(u, v):
        seen, stack = {u}, [u]
        while stack:
            x = stack.pop()
            if x == v:
                return True
            for y in adj[x]:
                if y not in seen:
                    seen.add(y); stack.append(y)
        return False

    return [reaches(u, v) for u, v in queries]

def check_if_prerequisite(n, prerequisites, queries):
    reach = [[False] * n for _ in range(n)]
    for a, b in prerequisites:
        reach[a][b] = True
    for k in range(n):
        for i in range(n):
            if reach[i][k]:
                row_k = reach[k]
                row_i = reach[i]
                for j in range(n):
                    if row_k[j]:
                        row_i[j] = True
    return [reach[u][v] for u, v in queries]

def check_if_prerequisite(n, prerequisites, queries):
    adj, indeg = defaultdict(list), [0] * n
    for a, b in prerequisites:
        adj[a].append(b)
        indeg[b] += 1
    anc = [0] * n                                # bit u set: u is a prerequisite
    queue = deque(u for u in range(n) if indeg[u] == 0)
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            anc[v] |= anc[u] | (1 << u)
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
    return [bool(anc[v] >> u & 1) for u, v in queries]
